INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00028000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 28), 'unit28-lesson1', 'Both … and: Connecting Two Items', '''Both … and'' is used to refer to two things or people together. It connects two nouns, adjectives, or phrases of the same grammatical type. The structure is ''Both + noun/adjective + and + noun/adjective''.', '{"details":[{"concept":"Both + noun + and + noun","explanation":"Use ''both … and'' to join two nouns that share the same action or quality.","example":"Both Alice and Susan have to comply with the rules.","burmese":"Both Alice and Susan have to comply with the rules."},{"concept":"Both + adjective + and + adjective","explanation":"Use ''both … and'' to join two adjectives describing the same subject.","example":"Sue is both kind and helpful to others.","burmese":"Sue is both kind and helpful to others."},{"concept":"Both + subject + and + subject + verb","explanation":"When ''both … and'' connects two subjects, the verb is always plural.","example":"Both the students and the teacher are in the class.","burmese":"Both the students and the teacher are in the class."}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00028001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 28), 'unit28-lesson2', 'Subject-Verb Agreement with Both … and', 'When ''both … and'' joins two subjects, the verb is always plural, even if one subject is singular. This is because ''both'' implies two things together, which is always treated as plural.', '{"details":[{"concept":"Plural verb with both … and","explanation":"Even if one subject is singular, use a plural verb when joining with ''both … and''.","example":"Both Tom and Ann were late.","burmese":"Both Tom and Ann were late."},{"concept":"Both … and with negative sentences","explanation":"In negative sentences, ''both … and'' uses the plural negative form.","example":"Both Daniel and Kim don''t drink tea.","burmese":"Both Daniel and Kim don''t drink tea."}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00028000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 28), 'unit28-ex1', 'multiple_choice', 'Combine the following sentences using ''both … and''.', '[{"id":2801,"question":"Fred likes helping his friends. Linda likes helping his friends. Combine using ''both … and''.","options":["Both Fred and Linda like helping their friends","Fred both likes and Linda helping their friends","Both likes Fred and Linda helping their friends"],"answer":"Both Fred and Linda like helping their friends","explanation":"Place ''Both'' before the first subject and ''and'' before the second. The verb ''like'' stays plural. ''Both … and'' ကို subject နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2802,"question":"The boy is intelligent. The boy is hardworking. Combine using ''both … and''.","options":["The boy is both intelligent and hardworking","The boy is both intelligent or hardworking","Both the boy intelligent and hardworking is"],"answer":"The boy is both intelligent and hardworking","explanation":"Place ''both'' after the verb and ''and'' between the two adjectives. ''Both … and'' ကို adjective နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2803,"question":"He spoke French fluently. He spoke French correctly. Combine using ''both … and''.","options":["He spoke both French fluently and correctly","He spoke both French fluently or correctly","Both he spoke French fluently and correctly"],"answer":"He spoke both French fluently and correctly","explanation":"Place ''both'' after the verb phrase and ''and'' between the two adverbs. ''Both … and'' ကို adverb နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2804,"question":"Mg Mg bought a new bike. Zaw Zaw bought a new bike. Combine using ''both … and''.","options":["Both Mg Mg and Zaw Zaw bought a new bike","Both Mg Mg and Zaw Zaw buys a new bike","Mg Mg both bought and Zaw Zaw a new bike"],"answer":"Both Mg Mg and Zaw Zaw bought a new bike","explanation":"Place ''Both'' before the first subject and ''and'' before the second. The past tense verb ''bought'' stays the same. ''Both … and'' ကို subject နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2805,"question":"James owns a shop. She owns a restaurant. Combine using ''both … and''.","options":["James owns both a shop and a restaurant","James owns both a shop or a restaurant","Both James owns a shop and a restaurant"],"answer":"James owns both a shop and a restaurant","explanation":"Place ''both'' after the verb and ''and'' between the two objects. ''Both … and'' ကို object နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2806,"question":"Jim likes ice hockey. Zak likes ice hockey. Combine using ''both … and''.","options":["Both Jim and Zak like ice hockey","Both Jim and Zak likes ice hockey","Jim both likes and Zak ice hockey"],"answer":"Both Jim and Zak like ice hockey","explanation":"Place ''Both'' before the first subject and ''and'' before the second. The plural verb ''like'' agrees with the compound subject. ''Both … and'' ကို subject နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2807,"question":"Ted can''t play golf. John can''t play golf. Combine using ''both … and''.","options":["Both Ted and John can''t play golf","Both Ted and John doesn''t play golf","Ted both can''t play and John golf"],"answer":"Both Ted and John can''t play golf","explanation":"Place ''Both'' before the first subject and ''and'' before the second. The negative modal ''can''t'' stays the same. ''Both … and'' ကို subject နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2808,"question":"Martha has got skates. Fiona has got skates. Combine using ''both … and''.","options":["Both Martha and Fiona have got skates","Both Martha and Fiona has got skates","Martha both has got and Fiona skates"],"answer":"Both Martha and Fiona have got skates","explanation":"Place ''Both'' before the first subject and ''and'' before the second. Use ''have'' (plural) because the compound subject is plural. ''Both … and'' ကို subject နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2809,"question":"Daniel doesn''t drink tea. Kim doesn''t drink tea. Combine using ''both … and''.","options":["Both Daniel and Kim don''t drink tea","Both Daniel and Kim doesn''t drink tea","Daniel both doesn''t drink and Kim tea"],"answer":"Both Daniel and Kim don''t drink tea","explanation":"Place ''Both'' before the first subject and ''and'' before the second. Use ''don''t'' (plural) because the compound subject is plural. ''Both … and'' ကို subject နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2810,"question":"Tom was late. Ann was late. Combine using ''both … and''.","options":["Both Tom and Ann were late","Both Tom and Ann was late","Tom both was late and Ann"],"answer":"Both Tom and Ann were late","explanation":"Place ''Both'' before the first subject and ''and'' before the second. Use ''were'' (plural) because the compound subject is plural. ''Both … and'' ကို subject နှစ်ခုကြားမှာ ထားပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

