INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00029000-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 29), 'unit29-lesson1', 'Not only … but also: Connecting and Emphasizing', '''Not only … but also'' is used to connect and emphasize two phrases or two words at the same position. Parallelism should be the goal — the words joined should be the same grammatical type (nouns with nouns, verbs with verbs, adjectives with adjectives).', '{"details":[{"concept":"Subject + verb + not only + noun/adj/adv + but also + noun/adj/adv","explanation":"Place ''not only'' before the first item and ''but also'' before the second item.","example":"He can speak not only English but also German.","burmese":"He can speak not only English but also German."},{"concept":"Subject + not only + verb + but also + verb","explanation":"When joining two verbs, place ''not only'' before the first verb and ''but also'' before the second.","example":"She not only dances extraordinarily but also sings perfectly.","burmese":"She not only dances extraordinarily but also sings perfectly."}]}'::jsonb, 1) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;
INSERT INTO lessons (id, unit_id, slug, title, content, data, sort_order) VALUES ('00029001-0000-4000-8000-000000000002', (SELECT id FROM units WHERE unit_number = 29), 'unit29-lesson2', 'Subject-Verb Agreement with Not only … but also', 'If one subject is singular and the other is plural, the verb form agrees with the subject that is nearest the verb. This rule is the same as with ''either … or'' and ''neither … nor''.', '{"details":[{"concept":"Verb agrees with nearest subject","explanation":"When subjects differ in number, the verb takes the form of the nearer subject.","example":"Not only the bears but also the lion escapes from the zoo.","burmese":"Not only the bears but also the lion escapes from the zoo."},{"concept":"Reversing subjects changes the verb","explanation":"When the order of subjects is reversed, the verb form may change to agree with the new nearest subject.","example":"Not only the lion but also the bears escape from the zoo.","burmese":"Not only the lion but also the bears escape from the zoo."}]}'::jsonb, 2) ON CONFLICT (unit_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, data = EXCLUDED.data, sort_order = EXCLUDED.sort_order;

INSERT INTO exercises (id, unit_id, slug, type, instructions, questions) VALUES ('00029000-0000-4000-8000-000000000003', (SELECT id FROM units WHERE unit_number = 29), 'unit29-ex1', 'multiple_choice', 'Combine the following sentences using ''not only … but also''.', '[{"id":2901,"question":"There are problems with the children. There are problems with their parents. Combine using ''not only … but also''.","options":["There are problems not only with the children but also with their parents","There are problems not only with the children or also with their parents","There not only are problems with the children but also with their parents"],"answer":"There are problems not only with the children but also with their parents","explanation":"Place ''not only'' before the first prepositional phrase and ''but also'' before the second. Keep the subject and verb at the beginning. ''Not only … but also'' ကို phrase နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2902,"question":"I sent him many letters. I tried to telephone him. Combine using ''not only … but also''.","options":["I not only sent him many letters but also tried to telephone him","I not only sent him many letters or also tried to telephone him","I sent not only him many letters but also tried to telephone him"],"answer":"I not only sent him many letters but also tried to telephone him","explanation":"Place ''not only'' before the first verb phrase and ''but also'' before the second verb phrase. ''Not only … but also'' ကို verb phrase နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2903,"question":"We visit our grandfather''s house in summer. We visit our grandfather''s house in winter. Combine using ''not only … but also''.","options":["We visit our grandfather''s house not only in summer but also in winter","We visit our grandfather''s house not only in summer or also in winter","We not only visit our grandfather''s house in summer but also in winter"],"answer":"We visit our grandfather''s house not only in summer but also in winter","explanation":"Place ''not only'' before the first time phrase and ''but also'' before the second. ''Not only … but also'' ကို time phrase နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2904,"question":"She can dance. She can sing. Combine using ''not only … but also''.","options":["She can not only dance but also sing","She can not only dance or also sing","She not only can dance but also to sing"],"answer":"She can not only dance but also sing","explanation":"Place ''not only'' after the modal verb and before the first verb, with ''but also'' before the second verb. ''Not only … but also'' ကို verb နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2905,"question":"They need food. They need medicine. Combine using ''not only … but also''.","options":["They need not only food but also medicine","They need not only food or also medicine","They not need only food but also medicine"],"answer":"They need not only food but also medicine","explanation":"Place ''not only'' before the first noun and ''but also'' before the second noun. ''Not only … but also'' ကို noun နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2906,"question":"She was upset. She was angry. Combine using ''not only … but also''.","options":["She was not only upset but also angry","She was not only upset or also angry","She not only was upset but also angry"],"answer":"She was not only upset but also angry","explanation":"Place ''not only'' after the verb ''was'' and before the first adjective, with ''but also'' before the second adjective. ''Not only … but also'' ကို adjective နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2907,"question":"John smokes. He drinks. Combine using ''not only … but also''.","options":["John not only smokes but also drinks","John not only smokes or also drinks","John smokes not only but also drinks"],"answer":"John not only smokes but also drinks","explanation":"Place ''not only'' before the first verb and ''but also'' before the second verb. ''Not only … but also'' ကို verb နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2908,"question":"Ann has been invited to the party. Mary has been invited to the party. Combine using ''not only … but also''.","options":["Not only Ann but also Mary has been invited to the party","Not only Ann but also Mary have been invited to the party","Ann not only has been invited but also Mary to the party"],"answer":"Not only Ann but also Mary has been invited to the party","explanation":"When the nearest subject is singular (''Mary''), the verb takes the singular form ''has''. ''Not only … but also'' ကို subject နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2909,"question":"Maria is clever. She is beautiful. Combine using ''not only … but also''.","options":["Maria is not only clever but also beautiful","Maria is not only clever or also beautiful","Maria not only is clever but also beautiful"],"answer":"Maria is not only clever but also beautiful","explanation":"Place ''not only'' after the verb ''is'' and before the first adjective, with ''but also'' before the second adjective. ''Not only … but also'' ကို adjective နှစ်ခုကြားမှာ ထားပါ။","points":1},{"id":2910,"question":"The cow gives us milk. The goat gives us milk. Combine using ''not only … but also''.","options":["Not only the cow but also the goat gives us milk","Not only the cow but also the goat give us milk","The cow not only gives us milk but also the goat"],"answer":"Not only the cow but also the goat gives us milk","explanation":"When the nearest subject is singular (''the goat''), the verb takes the singular form ''gives''. ''Not only … but also'' ကို subject နှစ်ခုကြားမှာ ထားပါ။","points":1}]'::jsonb) ON CONFLICT (unit_id, slug) DO UPDATE SET type = EXCLUDED.type, instructions = EXCLUDED.instructions, questions = EXCLUDED.questions;

